  "content": "1|import React, { useMemo, useState } from 'react';
2|import { AlertCircle, CheckCircle2, Loader2, Play } from 'lucide-react';
3|import { AppButton, UiTextarea } from '../../../shared/ui';
4|import { CreateEditModalShell } from '../../../shared/ui/CreateEditModalShell';
5|import { invokeAuthenticatedApiRoute } from '../../../shared/api/queries/server-functions';
6|import type { AccessibleApiRouteItem } from '../../../shared/api/contracts/my-apis/types';
7|
8|export type MyApiTestModalProps = {
9|  route: AccessibleApiRouteItem;
10|  onClose: () => void;
11|};
12|
13|export const MyApiTestModal: React.FC<MyApiTestModalProps> = ({ route, onClose }) => {
14|  const [payloadText, setPayloadText] = useState(route.testPayload);
15|  const [formError, setFormError] = useState<string | null>(null);
16|  const [isRunning, setIsRunning] = useState(false);
17|  const [output, setOutput] = useState<Record<string, unknown> | null>(null);
18|
19|  const outputText = useMemo(() => (
20|    output ? JSON.stringify(output, null, 2) : ''
21|  ), [output]);
22|
23|  const handleRun = async () => {
24|    setFormError(null);
25|    setOutput(null);
26|
27|    let parsedPayload: Record<string, unknown>;
28|    try {
29|      parsedPayload = JSON.parse(payloadText) as Record<string, unknown>;
30|    } catch {
31|      setFormError('Payload must be valid JSON.');
32|      return;
33|    }
34|
35|    setIsRunning(true);
36|    try {
37|      const { data } = await invokeAuthenticatedApiRoute({
38|        path: route.path,
39|        method: route.method,
40|        payload: parsedPayload,
41|        isDirectSql: route.engineType === 'DIRECT_SQL',
42|      });
43|      setOutput(data);
44|    } catch (error) {
45|      setOutput({
46|        success: false,
47|        error: error instanceof Error ? error.message : 'Request failed.',
48|      });
49|    } finally {
50|      setIsRunning(false);
51|    }
52|  };
53|
54|  const httpStatus = typeof output?._httpStatus === 'number' ? output._httpStatus : null;
55|  const requestFailed = Boolean(output?.error)
56|    || output?.success === false
57|    || (httpStatus !== null && (httpStatus < 200 || httpStatus >= 300));
58|
59|  return (
60|    <CreateEditModalShell
61|      size="maximized"
62|      bodyClassName="flex flex-col min-h-0 flex-1 overflow-hidden"
63|      title="Test API Route"
64|      onClose={onClose}
65|      onBackdropClick={onClose}
66|      footer={(
67|        <>
68|          <AppButton intent="cancel" onClick={onClose}>Close</AppButton>
69|          <AppButton intent="confirm" onClick={() => void handleRun()} disabled={isRunning}>
70|            {isRunning ? (
71|              <>
72|                <Loader2 className="h-3.5 w-3.5 animate-spin" />
73|                Running…
74|              </>
75|            ) : (
76|              <>
77|                <Play className="h-3.5 w-3.5" />
78|                Run
79|              </>
80|            )}
81|          </AppButton>
82|        </>
83|      )}
84|    >
85|      <div className="flex min-h-0 flex-1 flex-col gap-4">
86|        <div className="shrink-0 rounded-lg border border-slate-200 bg-slate-50/80 px-3 py-2">
87|          <p className="text-sm font-semibold text-slate-800">{route.name}</p>
88|          <p className="mt-1 font-mono text-xs text-slate-600">
89|            {route.method} {route.path}
90|          </p>
91|        </div>
92|
93|        <div className="flex min-h-0 flex-1 flex-col gap-[2px]">
94|          <label className="ps-[4px] text-xs font-semibold text-slate-600">Request payload (JSON)</label>
95|          <UiTextarea
96|            size="sm"
97|            value={payloadText}
98|            onChange={(event) => setPayloadText(event.target.value)}
99|            className="min-h-[160px] flex-1 font-mono text-xs"
100|          />
101|        </div>
102|
103|        {formError ? <p className="shrink-0 text-xs font-semibold text-rose-600">{formError}</p> : null}
104|
105|        {output ? (
106|          <div className="flex min-h-0 flex-1 flex-col gap-[2px]">
107|            <div className="flex shrink-0 items-center gap-2 ps-[4px]">
108|              {requestFailed ? (
109|                <AlertCircle className="h-4 w-4 text-rose-600" />
110|              ) : (
111|                <CheckCircle2 className="h-4 w-4 text-emerald-600" />
112|              )}
113|              <label className="text-xs font-semibold text-slate-600">
114|                Response
115|                {httpStatus !== null ? ` (HTTP ${httpStatus})` : ''}
116|              </label>
117|            </div>
118|            <UiTextarea
119|              size="sm"
120|              readOnly
121|              value={outputText}
122|              className="min-h-[180px] flex-1 font-mono text-xs"
123|            />
124|          </div>
125|        ) : null}
126|      </div>
127|    </CreateEditModalShell>
128|  );
129|};
130|"
}
